<template>
  <div class="page-stack">
    <section class="hero compact"><div><span class="eyebrow">SCHEMATIC CONVERSATIONS</span><h1>原理图生成总览</h1><p>汇总 LiteLLM 中的评测与普通会话，并将主 Agent 和 Subagent 组织为完整会话。</p></div></section>

    <el-card shadow="never" class="panel search-panel">
      <el-tabs v-model="source" @tab-change="search"><el-tab-pane label="全部会话" name="all"/><el-tab-pane label="评测会话" name="evaluation"/><el-tab-pane label="非评测会话" name="non_evaluation"/></el-tabs>
      <el-form label-position="top" @submit.prevent="search()"><div class="search-grid">
        <el-form-item label="时间范围"><el-date-picker v-model="timeRange" type="datetimerange" range-separator="至" start-placeholder="开始时间" end-placeholder="结束时间" :clearable="false"/></el-form-item>
        <el-form-item label="LiteLLM End User"><el-select v-model="endUser" filterable clearable allow-create placeholder="全部 End User"><el-option v-for="item in filterOptions.end_users" :key="item" :label="item" :value="item"/></el-select></el-form-item>
        <el-form-item label="会话 ID"><el-input v-model="sessionId" clearable placeholder="主会话或 Subagent session_id" @keyup.enter="search()"/></el-form-item>
        <el-form-item label="模型"><el-select v-model="selectedModel" filterable clearable placeholder="全部模型"><el-option v-for="item in filterOptions.models" :key="item" :label="item" :value="item"/></el-select></el-form-item>
        <el-form-item label="检索"><el-button native-type="submit" type="primary" :loading="loading">搜索</el-button></el-form-item>
      </div></el-form>
      <p class="search-note">默认只查询最近 24 小时。数据按根会话分页，一个主 Agent 及其全部 Subagent 不会被拆分。<span v-if="data.scan_truncated"> 当前列表基于时间范围内最近 {{number(data.scanned_interactions)}} 次调用。</span></p>
    </el-card>

    <div class="overview-metrics"><div><span>匹配会话</span><b>{{number(data.total)}}</b></div><div><span>当前交互</span><b>{{number(pageInteractions)}}</b></div><div><span>当前 Token</span><b>{{number(pageTokens)}}</b></div><div><span>当前 Subagent</span><b>{{number(pageSubagents)}}</b></div></div>

    <el-card shadow="never" class="panel list-panel">
      <template #header><div class="section-head"><div><b>会话列表</b><span>点击任意会话行查看完整输入、历史、输出和 Subagent 详情</span></div><el-tag effect="plain">{{data.conversations?.length||0}} 条</el-tag></div></template>
      <el-table v-if="data.conversations?.length" :data="data.conversations" v-loading="loading" row-key="root_session_id" row-class-name="conversation-row" @row-click="openConversation">
        <el-table-column label="开始时间" width="176" sortable><template #default="{row}">{{formatTime(row.started_at)}}</template></el-table-column>
        <el-table-column label="会话" min-width="250"><template #default="{row}"><div class="session-cell"><b>{{row.root_session_id}}</b><span>{{row.interaction_count||0}} 轮交互</span></div></template></el-table-column>
        <el-table-column label="用户" min-width="145" show-overflow-tooltip><template #default="{row}">{{conversationUser(row)}}</template></el-table-column>
        <el-table-column label="来源" width="100"><template #default="{row}"><el-tag size="small" :type="sourceType(row.source_kind)">{{sourceLabel(row.source_kind)}}</el-tag></template></el-table-column>
        <el-table-column label="Agent" width="120"><template #default="{row}">{{row.agent||'未记录'}}</template></el-table-column>
        <el-table-column label="模型" min-width="190" show-overflow-tooltip><template #default="{row}">{{row.models?.join('、')||'未记录'}}</template></el-table-column>
        <el-table-column label="交互" width="82" align="right"><template #default="{row}">{{number(row.interaction_count)}}</template></el-table-column>
        <el-table-column label="Subagent" width="100" align="right"><template #default="{row}">{{number(row.subagent_count)}}</template></el-table-column>
        <el-table-column label="Token" width="105" align="right"><template #default="{row}">{{number(row.total_tokens)}}</template></el-table-column>
        <el-table-column label="总用时" width="105" align="right"><template #default="{row}">{{duration(row.duration_ms)}}</template></el-table-column>
        <el-table-column label="操作" width="90" fixed="right"><template #default="{row}"><el-button link type="primary" @click.stop="openConversation(row)">查看详情</el-button></template></el-table-column>
      </el-table>
      <el-empty v-else-if="!loading" description="没有找到匹配的会话"/>
      <el-pagination v-if="data.total" v-model:current-page="sessionPage" v-model:page-size="sessionPageSize" background layout="total, sizes, prev, pager, next, jumper" :page-sizes="[20,50,100]" :total="data.total" class="session-pagination" @current-change="loadConversations" @size-change="changeSessionPageSize"/>
    </el-card>

    <el-dialog v-model="detailVisible" width="94%" top="3vh" append-to-body destroy-on-close class="conversation-dialog" @closed="resetDetail">
      <template #header><div class="dialog-title"><div><span class="eyebrow">CONVERSATION DETAIL</span><b>会话详情</b><small>{{detail?.root_session_id||selectedRoot}}</small></div><el-tag v-if="detail" :type="sourceType(detail.source_kind)">{{sourceLabel(detail.source_kind)}}</el-tag></div></template>
      <div v-loading="detailLoading" class="detail-shell">
        <template v-if="detail">
          <div class="detail-metrics"><div><span>起始时间</span><b>{{formatTime(detail.started_at)}}</b></div><div><span>总用时</span><b>{{duration(detail.duration_ms)}}</b></div><div><span>模型交互</span><b>{{number(detail.interaction_count)}}</b></div><div><span>总 Token</span><b>{{number(detail.total_tokens)}}</b></div><div><span>工具调用</span><b>{{number(detail.tool_call_count)}}</b></div><div><span>Subagent</span><b>{{number(detail.subagent_count)}}</b></div></div>
          <el-tabs v-model="detailView" class="detail-tabs">
            <el-tab-pane label="模型交互" name="timeline">
              <div class="interaction-toolbar"><el-input v-model="interactionKeyword" clearable placeholder="搜索提示词、历史、模型输出、工具或请求 ID"/><span>共 {{filteredInteractions.length}} 轮，按时间顺序完整显示</span></div>
              <div v-if="filteredInteractions.length" class="turn-list">
                <article v-for="(item,index) in filteredInteractions" :key="item.request_id||index" class="turn-card">
                  <header class="turn-title" @click="toggleInteraction(item)"><span class="sequence">{{index+1}}</span><div><b>{{item.model_group||item.model||'未知模型'}}</b><small>{{formatTime(item.start_time)}} · {{roleName(item)}} · {{item.session_id||'无 session_id'}}</small></div><div class="turn-meta"><el-tag size="small" :type="item.status==='success'?'success':'danger'">{{statusLabel(item.status)}}</el-tag><span>{{duration(item.request_duration_ms)}}</span><span>{{number(item.total_tokens)}} tokens</span><el-button link type="primary">{{isInteractionExpanded(item)?'收起':'展开详情'}}</el-button></div></header>
                  <div v-if="item._loading" class="turn-loading"><el-skeleton :rows="3" animated/></div>
                  <div v-else-if="isInteractionExpanded(item)" class="io-layout">
                    <section class="io-panel input-panel"><header><b>INPUT 输入</b><span>{{inputMessageCount(item)}} 条消息</span></header><div class="input-groups">
                      <div v-if="classifiedInput(item).system.length" class="message-group system-group"><h4>系统提示词 <span>{{classifiedInput(item).system.length}}</span></h4><div v-for="(message,messageIndex) in classifiedInput(item).system" :key="`system-${messageIndex}`" class="message system"><span class="role">{{roleLabel(message.role)}}</span><div><p>{{contentText(message.content)}}</p></div></div></div>
                      <div v-if="classifiedInput(item).user.length" class="message-group user-group"><h4>当前用户提示词 <span>{{classifiedInput(item).user.length}}</span></h4><div v-for="(message,messageIndex) in classifiedInput(item).user" :key="`user-${messageIndex}`" class="message user"><span class="role">用户</span><div><p>{{contentText(message.content)}}</p></div></div></div>
                      <div v-if="classifiedInput(item).history.length" class="message-group history-group"><h4>历史消息 <span>{{classifiedInput(item).history.length}}</span></h4><div v-for="(message,messageIndex) in classifiedInput(item).history" :key="`history-${messageIndex}`" class="message history"><span class="role">{{roleLabel(message.role)}}</span><div><p>{{contentText(message.content)}}</p><div v-if="message.tool_calls?.length" class="tool-list"><div v-for="tool in message.tool_calls" :key="tool.id||tool.function?.name"><b>历史工具调用 · {{tool.function?.name||tool.name}}</b><pre>{{readable(tool.function?.arguments||tool.arguments)}}</pre></div></div></div></div></div>
                      <div v-if="classifiedInput(item).tool.length" class="message-group tool-group"><h4>工具返回 <span>{{classifiedInput(item).tool.length}}</span></h4><div v-for="(message,messageIndex) in classifiedInput(item).tool" :key="`tool-${messageIndex}`" class="message tool"><span class="role">工具</span><div><p>{{contentText(message.content)}}</p></div></div></div>
                      <el-empty v-if="!inputMessageCount(item)" :image-size="54" description="本轮没有保存输入内容"/>
                    </div></section>
                    <section class="io-panel output-panel"><header><b>OUTPUT 输出</b><span>{{responseMessages(item).length}} 条消息</span></header><div v-if="responseMessages(item).length" class="output-content"><div v-for="(message,responseIndex) in responseMessages(item)" :key="`response-${responseIndex}`" class="message assistant"><span class="role">模型</span><div><p>{{contentText(message.content)}}</p><div v-if="message.tool_calls?.length" class="tool-list"><div v-for="tool in message.tool_calls" :key="tool.id||tool.call_id||tool.function?.name"><b>工具调用 · {{tool.function?.name||tool.name}}</b><pre>{{readable(tool.function?.arguments||tool.arguments)}}</pre></div></div></div></div></div><el-empty v-else :image-size="54" description="本轮没有保存模型输出"/><div v-if="errorText(item)" class="message error"><span class="role">错误</span><div><p>{{errorText(item)}}</p></div></div></section>
                  </div>
                  <footer class="turn-footer"><span>请求 {{item.request_id||'未记录'}}</span><span>层级 {{item.depth||0}}</span><span>输入 {{number(item.prompt_tokens)}} / 输出 {{number(item.completion_tokens)}}</span><span>工具 {{number(item.tool_call_count)}}</span></footer>
                  <details v-if="isInteractionExpanded(item)&&!item._loading" class="raw-log"><summary>完整请求 / 响应 / 元数据</summary><pre>{{JSON.stringify(item,null,2)}}</pre></details>
                </article>
              </div>
              <el-empty v-else description="没有匹配的模型交互"/>
            </el-tab-pane>
            <el-tab-pane label="主 Agent / Subagent" name="sessions"><div class="session-tree"><article v-for="node in detail.sessions" :key="node.session_id" :style="{marginLeft:`${Math.min(node.depth,6)*28}px`}"><span class="tree-line">{{node.depth?`SUBAGENT L${node.depth}`:'MAIN AGENT'}}</span><div><b>{{node.session_id}}</b><small v-if="node.parent_session_id">父会话：{{node.parent_session_id}}</small></div><div class="tree-stats"><span>{{node.interaction_count}} 次调用</span><span>{{number(node.total_tokens)}} tokens</span><span>{{duration(node.duration_ms)}}</span><span>{{node.models?.join('、')||'模型未记录'}}</span></div></article></div></el-tab-pane>
          </el-tabs>
        </template>
        <el-empty v-else-if="!detailLoading" description="没有读取到会话详情"/>
      </div>
    </el-dialog>
  </div>
</template>

<script setup>
import {computed,onMounted,ref} from 'vue'
import {ElMessage} from 'element-plus'
import {fetchSchematicConversation,fetchSchematicConversations,fetchSchematicInteractionDetail,fetchSchematicInteractionFilters} from '../api'

const endUser=ref(''),sessionId=ref(''),selectedModel=ref(''),source=ref('all'),loading=ref(false),detailLoading=ref(false),detailVisible=ref(false),selectedRoot=ref(''),detail=ref(null),detailView=ref('timeline'),interactionKeyword=ref(''),sessionPage=ref(1),sessionPageSize=ref(20)
const timeRange=ref([new Date(Date.now()-24*60*60*1000),new Date()])
const expandedInteractionIds=ref([])
const data=ref({total:0,conversations:[]}),filterOptions=ref({end_users:[],models:[]})
const pageInteractions=computed(()=>(data.value.conversations||[]).reduce((sum,item)=>sum+Number(item.interaction_count||0),0))
const pageTokens=computed(()=>(data.value.conversations||[]).reduce((sum,item)=>sum+Number(item.total_tokens||0),0))
const pageSubagents=computed(()=>(data.value.conversations||[]).reduce((sum,item)=>sum+Number(item.subagent_count||0),0))
const filteredInteractions=computed(()=>{const rows=detail.value?.timeline||[],keyword=interactionKeyword.value.trim().toLocaleLowerCase();return keyword?rows.filter(item=>JSON.stringify(item).toLocaleLowerCase().includes(keyword)):rows})

async function loadConversations(){if(loading.value)return;loading.value=true;try{data.value=await fetchSchematicConversations({end_user:endUser.value.trim()||undefined,session_id:sessionId.value.trim()||undefined,model:selectedModel.value||undefined,source:source.value,limit:sessionPageSize.value,offset:(sessionPage.value-1)*sessionPageSize.value,start_time:timeRange.value?.[0]?.toISOString(),end_time:timeRange.value?.[1]?.toISOString()})}catch(error){ElMessage.error(error.response?.data?.detail||error.message)}finally{loading.value=false}}
async function search(){sessionPage.value=1;await loadConversations()}
async function changeSessionPageSize(){sessionPage.value=1;await loadConversations()}
async function openConversation(conversation){selectedRoot.value=conversation.root_session_id;detailVisible.value=true;detailLoading.value=true;detail.value=null;detailView.value='timeline';interactionKeyword.value='';try{detail.value=await fetchSchematicConversation(conversation.root_session_id,{start_time:timeRange.value?.[0]?.toISOString(),end_time:timeRange.value?.[1]?.toISOString()})}catch(error){ElMessage.error(error.response?.data?.detail||error.message)}finally{detailLoading.value=false}}
async function toggleInteraction(item){const id=item.request_id;if(!id)return;const open=expandedInteractionIds.value.includes(id);if(open){expandedInteractionIds.value=expandedInteractionIds.value.filter(value=>value!==id);return}expandedInteractionIds.value=[...expandedInteractionIds.value,id];if(item.content_loaded)return;item._loading=true;try{Object.assign(item,await fetchSchematicInteractionDetail(id),{content_loaded:true})}catch(error){expandedInteractionIds.value=expandedInteractionIds.value.filter(value=>value!==id);ElMessage.error(error.response?.data?.detail||error.message)}finally{item._loading=false}}
const isInteractionExpanded=item=>expandedInteractionIds.value.includes(item.request_id)
function resetDetail(){detail.value=null;selectedRoot.value='';interactionKeyword.value='';expandedInteractionIds.value=[]}
function objectValue(value){if(typeof value==='string'){try{return JSON.parse(value)}catch{return value}}return value}
function requestMessages(item){const raw=objectValue(item.proxy_server_request)||{},request=objectValue(raw.body)||raw,messages=objectValue(request.messages||item.messages||request.input);if(Array.isArray(messages))return messages.map(message=>typeof message==='string'?{role:'user',content:message}:message);return typeof messages==='string'?[{role:'user',content:messages}]:[]}
function responseMessages(item){const response=objectValue(item.response)||{};if(Array.isArray(response.choices))return response.choices.map(choice=>choice.message||choice.delta).filter(Boolean);if(Array.isArray(response.output))return response.output.map(output=>({role:output.role||'assistant',content:output.content||output.summary||(output.type==='function_call'?'':output),tool_calls:output.type==='function_call'?[output]:output.tool_calls}));return response.content?[{role:'assistant',content:response.content}]:[]}
function classifiedInput(item){const messages=requestMessages(item);let currentUserIndex=-1;for(let index=messages.length-1;index>=0;index-=1){if(String(messages[index]?.role||'').toLowerCase()==='user'){currentUserIndex=index;break}}const result={system:[],user:[],history:[],tool:[]};messages.forEach((message,index)=>{const role=String(message?.role||'').toLowerCase();if(role==='system'||role==='developer')result.system.push(message);else if(role==='tool'||role==='function')result.tool.push(message);else if(index===currentUserIndex)result.user.push(message);else result.history.push(message)});return result}
const inputMessageCount=item=>requestMessages(item).length
function contentText(value){if(value==null||value==='')return'（无文本内容）';if(typeof value==='string')return value;if(Array.isArray(value))return value.map(part=>typeof part==='string'?part:(part.text||part.content||part.type||readable(part))).join('\n');return readable(value)}
function readable(value){if(value==null)return'—';if(typeof value==='string'){try{return readable(JSON.parse(value))}catch{return value}}if(Array.isArray(value))return value.map(readable).join('\n');return Object.entries(value).map(([key,item])=>`${key}: ${typeof item==='object'?readable(item):item}`).join('\n')}
const errorText=item=>item.metadata?.error_information?.error_message||item.metadata?.error_information?.error||''
const roleLabel=role=>({user:'用户',assistant:'模型',system:'系统',developer:'开发者',tool:'工具',function:'工具'}[String(role||'').toLowerCase()]||role||'消息').toUpperCase()
const roleName=item=>item.depth?`Subagent L${item.depth}`:'主 Agent'
const conversationUser=row=>row.end_user||row.user_id||'未记录'
const sourceLabel=value=>({evaluation:'评测',non_evaluation:'非评测',mixed:'混合'}[value]||value||'未知')
const sourceType=value=>value==='evaluation'?'warning':value==='mixed'?'info':'success'
const statusLabel=value=>({success:'成功',failure:'失败',failed:'失败'}[String(value||'').toLowerCase()]||value||'未知')
const number=value=>value==null?'—':Number(value).toLocaleString(),duration=value=>value==null?'—':Number(value)>=1000?`${(Number(value)/1000).toFixed(1)} 秒`:`${value} ms`,formatTime=value=>value?new Date(value).toLocaleString('zh-CN'):'未记录'
onMounted(async()=>{try{filterOptions.value=await fetchSchematicInteractionFilters()}catch{}await loadConversations()})
</script>

<style scoped>
.search-panel :deep(.el-form-item){margin:0}.search-panel :deep(.el-select){width:100%}.search-grid{display:grid;grid-template-columns:1.15fr 1fr 1fr 110px;align-items:end;gap:14px}.search-grid .el-button{width:100%}.search-note{margin:12px 0 0;color:var(--muted);font-size:12px}.overview-metrics,.detail-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.overview-metrics>div,.detail-metrics>div{display:flex;flex-direction:column;padding:17px 19px;background:var(--surface);border:1px solid var(--line);border-radius:10px}.overview-metrics span,.detail-metrics span{color:var(--muted);font-size:11px}.overview-metrics b{font-size:24px;margin-top:5px}.section-head,.dialog-title,.turn-title{display:flex;align-items:center;justify-content:space-between;gap:18px}.section-head>div,.dialog-title>div{display:flex;flex-direction:column;gap:3px;min-width:0}.section-head span,.dialog-title small{color:var(--muted);font-size:12px;overflow-wrap:anywhere}.list-panel :deep(.conversation-row){cursor:pointer}.session-cell{display:flex;flex-direction:column;gap:4px;min-width:0}.session-cell b,.session-cell span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.session-cell span{color:var(--muted);font-size:11px}.session-pagination{display:flex;justify-content:flex-end;margin-top:18px}.detail-shell{min-height:220px;max-height:78vh;overflow-y:auto;padding-right:5px}.detail-metrics{grid-template-columns:repeat(6,1fr);margin-bottom:16px}.detail-metrics>div{background:var(--surface-2);box-shadow:none}.detail-metrics b{font-size:14px;margin-top:5px;overflow-wrap:anywhere}.detail-tabs{margin-top:8px}.interaction-toolbar{display:flex;align-items:center;justify-content:space-between;gap:18px;margin:2px 0 14px}.interaction-toolbar .el-input{max-width:620px}.interaction-toolbar span{color:var(--muted);font-size:12px;white-space:nowrap}.turn-list{display:grid;gap:16px}.turn-card{overflow:hidden;border:1px solid var(--line);border-radius:10px;background:var(--surface)}.turn-card>.turn-title{min-height:72px;padding:12px 16px;background:var(--surface-2)}.turn-title{width:100%}.turn-title>.sequence{flex:0 0 auto}.turn-title>div:nth-child(2){display:flex;flex:1;flex-direction:column;min-width:0}.turn-title small{color:var(--muted);font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.sequence{display:grid;place-items:center;width:28px;height:28px;border-radius:50%;background:var(--brand-soft);color:var(--brand);font-weight:700;font-size:12px}.turn-meta{display:flex!important;align-items:center;gap:12px;color:var(--muted);font-size:12px}.io-layout{display:grid;grid-template-columns:1fr 1fr;border-top:1px solid var(--line)}.io-panel{min-width:0;background:var(--surface)}.io-panel+.io-panel{border-left:1px solid var(--line)}.io-panel>header{display:flex;align-items:center;justify-content:space-between;padding:13px 16px;border-bottom:1px solid var(--line)}.io-panel>header b{font-size:12px;letter-spacing:.04em}.io-panel>header span{color:var(--muted);font-size:11px}.input-groups,.output-content{display:grid;gap:13px;padding:15px}.message-group{display:grid;gap:8px}.message-group h4{display:flex;align-items:center;gap:7px;margin:0;color:var(--muted);font-size:11px;text-transform:uppercase}.message-group h4 span{display:inline-flex;align-items:center;justify-content:center;min-width:19px;height:19px;padding:0 5px;border-radius:10px;background:var(--surface-2);font-size:10px}.message{display:grid;grid-template-columns:68px minmax(0,1fr);gap:10px;padding:12px 13px;border-radius:8px;background:var(--surface-2)}.message.system{background:#f2f3f5}.message.user{background:#eef5ff}.message.history{background:#f7f8fa;border-left:3px solid #a8b0ba}.message.tool{background:#fff8e8}.message.assistant{background:var(--brand-soft)}.message.error{margin:0 15px 15px;background:#fff0f0;color:var(--red)}.message .role{color:var(--muted);font-size:10px;font-weight:750;letter-spacing:.05em}.message p{margin:0;white-space:pre-wrap;line-height:1.65;